client = ChatOpenAI(
    model=DEFAULT_MODEL, 
    api_key=api_key, 
    base_url=base_url, 
    temperature=0,
    streaming=True  # 启用流式传输
    )

class Agent:
    def execute(self):
        &#39;&#39;&#39;
        completion = client.chat.completions.create(
            model=DEFAULT_MODEL,
            messages=self.messages,
            temperature=0
        )
        return completion.choices[0].message.content
        &#39;&#39;&#39;
        full_response = []
